@import "tailwindcss";

@theme {
  --color-primary: #02838D;
  --color-primary-foreground: #FFFFFF;
  --color-secondary: #F0F4F4;
  --color-secondary-foreground: #02838D;
  --color-accent: #FF7043;
  --color-accent-foreground: #FFFFFF;
  --color-background: #FAFAFA;
  --color-foreground: #231F20;
  --color-muted: #F3F4F6;
  --color-muted-foreground: #6B7280;
  --color-card: #FFFFFF;
  --color-card-foreground: #231F20;
  --color-border: #E5E7EB;
  --color-input: #E5E7EB;
  --color-ring: #02838D;

  --radius-lg: 0.75rem;
  --radius-md: 0.5rem;
  --radius-sm: 0.25rem;
}

@layer base {
  :root {
    --background: 0 0% 98%; /* #FAFAFA */
    --foreground: 0 0% 13%; /* #231F20 */
    --card: 0 0% 100%;
    --card-foreground: 0 0% 13%;
    --popover: 0 0% 100%;
    --popover-foreground: 0 0% 13%;
    --primary: 184 97% 28%; /* #02838D */
    --primary-foreground: 0 0% 100%;
    --secondary: 180 20% 95%; /* #F0F4F4 */
    --secondary-foreground: 184 97% 28%;
    --muted: 210 40% 96.1%;
    --muted-foreground: 215.4 16.3% 46.9%;
    --accent: 14 100% 63%; /* #FF7043 */
    --accent-foreground: 0 0% 100%;
    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 210 40% 98%;
    --border: 214.3 31.8% 91.4%;
    --input: 214.3 31.8% 91.4%;
    --ring: 184 97% 28%;
    --radius: 0.75rem;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
  }
}

@keyframes ticker {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.animate-ticker {
  animation: ticker 25s linear infinite;
}

.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

