import React, { useRef } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

export default function HealthTopics() {
  const topics = [
    { name: 'Anxiety & Depression', color: 'bg-teal-100 text-teal-800' },
    { name: 'Digestive Health', color: 'bg-amber-100 text-amber-800' },
    { name: 'Heart Health', color: 'bg-rose-100 text-rose-800' },
    { name: 'Menopause', color: 'bg-indigo-100 text-indigo-800' },
    { name: 'Type 2 Diabetes', color: 'bg-blue-100 text-blue-800' },
    { name: 'Weight Management', color: 'bg-green-100 text-green-800' },
    { name: 'Skin Care', color: 'bg-orange-100 text-orange-800' },
    { name: 'Sleep Health', color: 'bg-purple-100 text-purple-800' },
  ];

  const scrollRef = useRef<HTMLDivElement>(null);

  const scroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      const { scrollLeft, clientWidth } = scrollRef.current;
      const scrollTo = direction === 'left' ? scrollLeft - clientWidth / 2 : scrollLeft + clientWidth / 2;
      scrollRef.current.scrollTo({ left: scrollTo, behavior: 'smooth' });
    }
  };

  return (
    <div className="container mx-auto px-4 md:px-6 max-w-7xl">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-2xl md:text-3xl font-bold tracking-tight">Health Topics</h2>

        <div className="flex items-center gap-4">
          <a href="#" className="hidden md:block font-bold text-primary hover:text-accent transition-colors">
            View all
          </a>
          <div className="flex gap-2">
            <button 
              onClick={() => scroll('left')}
              className="p-2 rounded-full border border-border bg-white hover:bg-secondary transition-colors text-foreground"
              aria-label="Scroll left"
            >
              <ChevronLeft size={20} />
            </button>
            <button 
              onClick={() => scroll('right')}
              className="p-2 rounded-full border border-border bg-white hover:bg-secondary transition-colors text-foreground"
              aria-label="Scroll right"
            >
              <ChevronRight size={20} />
            </button>
          </div>
        </div>
      </div>

      <div className="relative -mx-4 md:mx-0">
        <div 
          ref={scrollRef}
          className="flex overflow-x-auto gap-4 md:gap-6 px-4 md:px-0 snap-x snap-mandatory no-scrollbar pb-4"
        >
          {topics.map((topic, i) => (
            <a 
              key={topic.name} 
              href="#" 
              className="flex flex-col items-center gap-3 shrink-0 snap-start w-[140px] md:w-[160px] group"
            >
              <div className={`w-[120px] h-[120px] md:w-[140px] md:h-[140px] rounded-full flex items-center justify-center p-6 text-center ${topic.color} transition-transform group-hover:scale-105 shadow-sm`}>
                <span className="font-bold text-sm md:text-base leading-tight">
                  {topic.name}
                </span>
              </div>
              <span className="font-semibold text-center group-hover:text-primary transition-colors line-clamp-2 px-2">
                {topic.name}
              </span>
            </a>
          ))}
        </div>
      </div>

      <div className="mt-4 text-center md:hidden">
        <a href="#" className="font-bold text-primary hover:text-accent transition-colors">
          View all health topics
        </a>
      </div>
    </div>
  );
}

